import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.CYjxsSA2.js";const m=JSON.parse('{"title":"无头浏览器与取证","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/browser.md","filePath":"advanced/browser.md"}'),o={name:"advanced/browser.md"};function l(n,t,i,s,h,c){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="无头浏览器与取证" tabindex="-1">无头浏览器与取证 <a class="header-anchor" href="#无头浏览器与取证" aria-label="Permalink to &quot;无头浏览器与取证&quot;">​</a></h1><p>军团配备一个<strong>真实浏览器</strong>（Chrome / Chromium），用于渲染、交互与取证 —— SPA 不再是盲区。</p><h2 id="能力" tabindex="-1">能力 <a class="header-anchor" href="#能力" aria-label="Permalink to &quot;能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>动作</th></tr></thead><tbody><tr><td>导航</td><td>打开 URL、等待加载、标签页管理</td></tr><tr><td>交互</td><td>点击、输入、表单发现与提交、链接发现</td></tr><tr><td>渲染</td><td>SPA 渲染，补抓动态接口</td></tr><tr><td>取证</td><td>截图、网络日志、请求详情、登录态导出</td></tr><tr><td>判定</td><td>登录结果判定、页面内容读取</td></tr></tbody></table><p>取证产物（截图、DOM 快照、原始请求响应）会进入项目证据链，可在<a href="/vaelor/guide/vulnreports.html">漏洞管理</a>回溯。</p><h2 id="运行方式" tabindex="-1">运行方式 <a class="header-anchor" href="#运行方式" aria-label="Permalink to &quot;运行方式&quot;">​</a></h2><p>默认在后台运行，不弹窗口；你不用管它，取证产物会自己落到项目里。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>随包浏览器优先，其次使用系统 Chrome；两者都没有时，浏览器相关能力不可用</li><li>目标加载过慢时会退化为<strong>静态快照</strong>：能拿到内容，但取证强度下降。遇到「截图与预期不符」先考虑这一点</li><li>浏览器操作受<strong>权限档位</strong>约束：只读档位下不会执行写入类交互</li><li>军团在浏览器中的所有动作都会留痕，可在会话中逐步回看</li></ul>',9)])])}const p=a(o,[["render",l]]);export{m as __pageData,p as default};
